#include <bits/stdc++.h>
using namespace std;

int main() {
	// your code goes here
	int t;
	cin>>t;
	while(t--){
	    int n;
	    cin>>n;
	    vector<long long >a(3*n);
	    for(int i=0;i<3*n;i++){
	        cin>>a[i];
	    }
	    sort(a.begin(),a.end());
	    vector<long long>pre(3*n+1,0);
	    for(int i=0;i<3*n;i++){
	        pre[i+1]=pre[i]+a[i];
	    }
	    auto get=[&](int l,int r)->long long{
	        if(l>r) return 0LL;
	        return pre[r]-pre[l-1];
	    };
	    auto calc=[&](int k1,int k2)->long long {
	        int k3=n-k1-k2;
	        long long s1=6*get(3*n-k1+1,3*n);
	        long long s2=4*get(3*n-k1-2*k2+1,3*n-k1);
	        long long s3=3*get(3*n-k1-2*k2-3*k3+1,3*n-k1-2*k2);
	        return s1+s2+s3;
	    };
	    long long maxi=0LL;
	    
	    for(int k1=0;k1<=n;k1++){
	        int left=0;
	        int right=n-k1;
	        long long bestk1=0;
	        while(right-left>=3) {
	            int mid1=left+(right-left)/3;
	            int mid2=right-(right-left)/3;
	            long long ans1=calc(k1,mid1);
	            long long ans2=calc(k1,mid2);
	            
	            if(ans1<ans2) left=mid1;
	            else right=mid2;
	        }
	        for(int k2=left;k2<=right;k2++){
	            bestk1=max(bestk1,calc(k1,k2));
	        }
	        maxi=max(maxi,bestk1);
	    }
	    
	    cout<<maxi<<"\n";
	    
	}
}
